$now=epoch('2026-10-26 07:00');foreach(['Away','Do Not Disturb','Custom 1']as$status){$c=fixture();$c['users']['2001']['profile']=$status;check(pbx_mobile_state::profile($c['users']['2001'],$c,'2001',$now)===$status,'Personal status changed');}
$c=fixture();$c['users']['2001']['auto_status']='0';check(pbx_mobile_state::profile($c['users']['2001'],$c,'2001',$now)==='Out of office','Automatic disabled ignored');
$c=fixture();$c['users']['2001']['mobile_temporary']=['target'=>'Out of office','previous'=>'Available','expires'=>$now+60];check(pbx_mobile_state::profile($c['users']['2001'],$c,'2001',$now)==='Out of office','Active temporary ignored');$c['users']['2001']['mobile_temporary']['expires']=$now-1;check(pbx_mobile_state::profile($c['users']['2001'],$c,'2001',$now)==='Available','Expired temporary return failed');
$c=fixture();unset($c['users']['2001']['profiles']['Available']);check(pbx_mobile_state::profile($c['users']['2001'],$c,'2001',$now)==='Out of office','Missing profile fabricated');
$c=fixture();$c['departments']=[];check(pbx_mobile_state::profile($c['users']['2001'],$c,'2001',$now)==='Out of office','Unassigned default behavior changed');
$c=fixture();$c['departments'][0]['office_override']=['state'=>'closed','expires'=>$now+60];check(pbx_mobile_state::profile($c['users']['2001'],$c,'2001',$now)==='Out of office','Closed override ignored');
$c=fixture();$c['departments'][0]['breaks']=['type'=>'SpecificHours','periods'=>[['day'=>1,'start'=>'07:00','end'=>'08:00']]];check(pbx_mobile_state::profile($c['users']['2001'],$c,'2001',$now)==='Away','Break ignored');
$c=fixture();$c['departments'][0]['holidays']=[['date'=>'2026-10-26']];check(pbx_mobile_state::profile($c['users']['2001'],$c,'2001',$now)==='Out of office','Holiday ignored');
